cat > tests/services/organization-lifecycle.test.ts <<'EOF'
/**
 * Deleting a workspace starts a grace period; restoring works inside it and
 * the retention sweep purges it afterwards.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { DELETED_WORKSPACE_RETENTION_DAYS } from "@/config/constants";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import { NotFoundError } from "@/server/services/_support";
import { resolveActorForOrg } from "@/server/services/session-service";
import {
  deleteOrganization,
  restoreOrganization,
} from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { SessionPrincipal } from "@/types/member";
import type { UserId } from "@/types/common";

let cleanup: () => void;
let detach: () => void;
let tenant: Tenant;

const DAY = 24 * 60 * 60 * 1000;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = registerActivityListeners();
  tenant = await createTenant("lifecycle");
  await usageRepo.recomputeUsage(tenant.org.id);
});

afterAll(() => {
  detach();
  cleanup();
});

describe("organization deletion lifecycle", () => {
  it("deletes, hides, restores and purges", async () => {
    const { org, actors, userIds } = tenant;

    const deleted = await deleteOrganization(actors.owner, {
      orgId: org.id,
      confirmSlug: org.slug,
    });
    expect(deleted.archivedAt).not.toBeNull();

    await expect(
      deleteOrganization(actors.owner, { orgId: org.id, confirmSlug: org.slug }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);

    const principal = {
      userId: userIds.owner,
      email: "x",
      activeOrgId: null,
      expiresAt: deleted.archivedAt,
    } as unknown as SessionPrincipal;
    await expect(resolveActorForOrg(principal, org.slug)).resolves.toBeNull();
    expect(await orgRepo.listOrgsForUser(userIds.owner)).toHaveLength(0);
    expect(await usageRepo.listOrgIdsForRollup(10)).not.toContain(org.id);

    await expect(
      restoreOrganization(userIds.admin, org.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      restoreOrganization("nobody" as UserId, org.id),
    ).rejects.toBeInstanceOf(NotFoundError);

    const restored = await restoreOrganization(userIds.owner, org.id);
    expect(restored.archivedAt).toBeNull();
    expect(await restoreOrganization(userIds.owner, org.id)).toEqual(restored);

    const audit = await activityRepo.listActivityForSubject(
      org.id,
      "organization",
      org.id,
    );
    expect(audit.map((row) => row.action).sort()).toEqual([
      "organization.deleted",
      "organization.restored",
    ]);

    // Live workspaces are never purged.
    const far = new Date(Date.now() + 1000 * DAY);
    await runCleanupArchivedJob(far);
    expect(await orgRepo.findOrgById(org.id)).not.toBeNull();

    await deleteOrganization(actors.owner, { orgId: org.id, confirmSlug: org.slug });
    const deletedAt = new Date((await orgRepo.findOrgById(org.id))!.archivedAt!);

    await runCleanupArchivedJob(
      new Date(deletedAt.getTime() + DELETED_WORKSPACE_RETENTION_DAYS * DAY - 1),
    );
    expect(await orgRepo.findOrgById(org.id)).not.toBeNull();

    await runCleanupArchivedJob(
      new Date(deletedAt.getTime() + DELETED_WORKSPACE_RETENTION_DAYS * DAY),
    );
    expect(await orgRepo.findOrgById(org.id)).toBeNull();
    expect(await orgRepo.listTakenOrgSlugs(org.slug)).toHaveLength(0);
    await expect(
      restoreOrganization(userIds.owner, org.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
});
EOF
